NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2003745070292938759\', \'2003745070292938753\', \'导出项目表\', NULL, \'ewmProjectExport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\n\"},{\"codeFileName\":\"Oracle.sql\",\"codeFileWithPathName\":\"sql\\\\Oracle.sql\",\"codeFileContent\":\"/*\\n Source Server Type: Oracle\\n Date:  2025/12/24 16:30\\n*/\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938753\', \'0\', \'项目表管理\', \'project\', \'mruCFKRrDB\', \'MENU\', \'1548901111999773976\', \'MENU\', \'/ewm/project\', \'ewm/project/index\', NULL, NULL, NULL, NULL, NULL, \'99\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938754\', \'2003745070292938753\', \'新增项目表\', NULL, \'ewmProjectAdd\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'1\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938757\', \'2003745070292938753\', \'批量删除项目表\', NULL, \'ewmProjectBatchDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'2\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938755\', \'2003745070292938753\', \'编辑项目表\', NULL, \'ewmProjectEdit\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'3\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938756\', \'2003745070292938753\', \'删除项目表\', NULL, \'ewmProjectDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'4\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938758\', \'2003745070292938753\', \'导入项目表\', NULL, \'ewmProjectImport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'5\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2003745070292938759\', \'2003745070292938753\', \'导出项目表\', NULL, \'ewmProjectExport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'6\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\n\"}],\"genBasicCodeFrontendResultList\":[{\"codeFileName\":\"ewmProjectApi.js\",\"codeFileWithPathName\":\"api\\\\ewm\\\\ewmProjectApi.js\",\"codeFileContent\":\"import { baseRequest } from \'@/utils/request\'\\n\\nconst request = (url, ...arg) => baseRequest(`/ewm/project/` + url, ...arg)\\n\\n/**\\n * 项目表Api接口管理器\\n *\\n * @author Richai\\n * @date  2025/12/24 16:30\\n **/\\nexport default {\\n\\t// 获取项目表分页\\n\\tewmProjectPage(data) {\\n\\t\\treturn request(\'page\', data, \'get\')\\n\\t},\\n\\t// 提交项目表表单 edit为true时为编辑，默认为新增\\n\\tewmProjectSubmitForm(data, edit = false) {\\n\\t\\treturn request(edit ? \'edit\' : \'add\', data)\\n\\t},\\n\\t// 删除项目表\\n\\tewmProjectDelete(data) {\\n\\t\\treturn request(\'delete\', data)\\n\\t},\\n\\t// 获取项目表详情\\n\\tewmProjectDetail(data) {\\n\\t\\treturn request(\'detail\', data, \'get\')\\n\\t},\\n\\t// 下载项目表导入模板\\n    ewmProjectDownloadTemplate(data) {\\n        return request(\'downloadImportTemplate\', data, \'get\', {\\n            responseType: \'blob\'\\n        })\\n    },\\n    // 导入项目表\\n    ewmProjectImport(data) {\\n        return request(\'importData\', data)\\n    },\\n    // 导出项目表\\n    ewmProjectExport(data) {\\n        return request(\'exportData\', data, \'post\', {\\n            responseType: \'blob\'\\n        })\\n    }\\n}\\n\"},{\"codeFileName\":\"form.vue\",\"codeFileWithPathName\":\"views\\\\ewm\\\\project\\\\form.vue\",\"codeFileContent\":\"<template>\\n\\t<xn-form-container\\n\\t\\t:title=\\\"formData.id ? \'编辑项目表\' : \'增加项目表\'\\\"\\n\\t\\t:width=\\\"700\\\"\\n\\t\\tv-model:open=\\\"open\\\"\\n\\t\\t:destroy-on-close=\\\"true\\\"\\n\\t\\t@close=\\\"onClose\\\"\\n\\t>\\n\\t\\t<a-form ref=\\\"formRef\\\" :model=\\\"formData\\\" :rules=\\\"formRules\\\" layout=\\\"vertical\\\">\\n\\t\\t\\t<a-row :gutter=\\\"16\\\">\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目名称：\\\" name=\\\"projectName\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectName\\\" placeholder=\\\"请输入项目名称\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目负责人：\\\" name=\\\"projectLeader\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectLeader\\\" placeholder=\\\"请输入项目负责人\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"排序码：\\\" name=\\\"sortCode\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.sortCode\\\" placeholder=\\\"请输入排序码\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"扩展信息：\\\" name=\\\"extJson\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.extJson\\\" placeholder=\\\"请输入扩展信息\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"机构id：\\\" name=\\\"orgId\\\">\\n\\t\\t\\t\\t\\t\\t<a-select v-model:value=\\\"formData.orgId\\\" placeholder=\\\"请选择机构id\\\" :options=\\\"orgIdOptions\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目状态，WAIT-待开始,LOADING-进行中,OPERATION-运维中,STOP-项目结束：\\\" name=\\\"peojectStatus\\\">\\n\\t\\t\\t\\t\\t\\t<a-select v-model:value=\\\"formData.peojectStatus\\\" placeholder=\\\"请选择项目状态，WAIT-待开始,LOADING-进行中,OPERATION-运维中,STOP-项目结束\\\" :options=\\\"peojectStatusOptions\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目类别，integration-系统集成，develop-开发，safe-安全：\\\" name=\\\"projectType\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectType\\\" placeholder=\\\"请输入项目类别，integration-系统集成，develop-开发，safe-安全\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目金额：\\\" name=\\\"projectMoney\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectMoney\\\" placeholder=\\\"请输入项目金额\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目开始日期：\\\" name=\\\"projectStartTime\\\">\\n\\t\\t\\t\\t\\t\\t<a-date-picker v-model:value=\\\"formData.projectStartTime\\\" value-format=\\\"YYYY-MM-DD HH:mm:ss\\\" show-time placeholder=\\\"请选择项目开始日期\\\" style=\\\"width: 100%\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目结束日期：\\\" name=\\\"projectEndTime\\\">\\n\\t\\t\\t\\t\\t\\t<a-date-picker v-model:value=\\\"formData.projectEndTime\\\" value-format=\\\"YYYY-MM-DD HH:mm:ss\\\" show-time placeholder=\\\"请选择项目结束日期\\\" style=\\\"width: 100%\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目说明：\\\" name=\\\"projectDesc\\\">\\n\\t\\t\\t\\t\\t\\t<xn-editor v-model:value=\\\"formData.projectDesc\\\" placeholder=\\\"请输入项目说明\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t</a-row>\\n\\t\\t</a-form>\\n\\t\\t<template #footer>\\n\\t\\t\\t<a-button style=\\\"margin-right: 8px\\\" @click=\\\"onClose\\\">关闭</a-button>\\n\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"onSubmit\\\" :loading=\\\"submitLoading\\\">保存</a-button>\\n\\t\\t</template>\\n\\t</xn-form-container>\\n</template>\\n\\n<script setup name=\\\"ewmProjectForm\\\">\\n\\timport tool from \'@/utils/tool\'\\n\\timport { cloneDeep } from \'lodash-es\'\\n\\timport { required } from \'@/utils/formRules\'\\n\\timport ewmProjectApi from \'@/api/ewm/ewmProjectApi\'\\n\\t// 抽屉状态\\n\\tconst open = ref(false)\\n\\tconst emit = defineEmits({ successful: null })\\n\\tconst formRef = ref()\\n\\t// 表单数据\\n\\tconst formData = ref({})\\n\\tconst submitLoading = ref(false)\\n\\tconst orgIdOptions = ref([])\\n\\tconst peojectStatusOptions = ref([])\\n\\n\\t// 打开抽屉\\n\\tconst onOpen = (record) => {\\n\\t\\topen.value = true\\n\\t\\tif (record) {\\n\\t\\t\\tlet recordData = cloneDeep(record)\\n\\t\\t\\tformData.value = Object.assign({}, recordData)\\n\\t\\t}\\n\\t\\torgIdOptions.value = tool.dictList(\'ORG_CATEGORY\')\\n\\t\\tpeojectStatusOptions.value = tool.dictList(\'PEOJECT_STATUS\')\\n\\t}\\n\\t// 关闭抽屉\\n\\tconst onClose = () => {\\n\\t\\tformRef.value.resetFields()\\n\\t\\tformData.value = {}\\n\\t\\topen.value = false\\n\\t}\\n\\t// 默认要校验的\\n\\tconst formRules = {\\n\\t\\tprojectName: [required(\'请输入项目名称\')],\\n\\t\\tprojectLeader: [required(\'请输入项目负责人\')],\\n\\t\\torgId: [required(\'请输入机构id\')],\\n\\t\\tpeojectStatus: [required(\'请输入项目状态，WAIT-待开始,LOADING-进行中,OPERATION-运维中,STOP-项目结束\')],\\n\\t}\\n\\t// 验证并提交数据\\n\\tconst onSubmit = () => {\\n\\t\\tformRef.value\\n\\t\\t\\t.validate()\\n\\t\\t\\t.then(() => {\\n\\t\\t\\t\\tsubmitLoading.value = true\\n\\t\\t\\t\\tconst formDataParam = cloneDeep(formData.value)\\n\\t\\t\\t\\tewmProjectApi\\n\\t\\t\\t\\t\\t.ewmProjectSubmitForm(formDataParam, formDataParam.id)\\n\\t\\t\\t\\t\\t.then(() => {\\n\\t\\t\\t\\t\\t\\tonClose()\\n\\t\\t\\t\\t\\t\\temit(\'successful\')\\n\\t\\t\\t\\t\\t})\\n\\t\\t\\t\\t\\t.finally(() => {\\n\\t\\t\\t\\t\\t\\tsubmitLoading.value = false\\n\\t\\t\\t\\t\\t})\\n\\t\\t\\t})\\n\\t\\t\\t.catch(() => {})\\n\\t}\\n\\t// 抛出函数\\n\\tdefineExpose({\\n\\t\\tonOpen\\n\\t})\\n</script>\\n\"},{\"codeFileName\":\"index.vue\",\"codeFileWithPathName\":\"views\\\\ewm\\\\project\\\\index.vue\",\"codeFileContent\":\"<template>\\n\\t<a-card :bordered=\\\"false\\\" style=\\\"width: 100%\\\">\\n\\t\\t<a-form ref=\\\"searchFormRef\\\" :model=\\\"searchFormState\\\">\\n\\t\\t\\t<a-row :gutter=\\\"10\\\">\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"6\\\" :md=\\\"6\\\" :lg=\\\"6\\\" :xl=\\\"6\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目名称\\\" name=\\\"projectName\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"searchFormState.projectName\\\" placeholder=\\\"请输入项目名称\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"6\\\" :md=\\\"6\\\" :lg=\\\"6\\\" :xl=\\\"6\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"项目负责人\\\" name=\\\"projectLeader\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"searchFormState.projectLeader\\\" placeholder=\\\"请输入项目负责人\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"6\\\" :md=\\\"6\\\" :lg=\\\"6\\\" :xl=\\\"6\\\">\\n\\t\\t\\t\\t    <a-form-item>\\n\\t\\t\\t\\t        <a-space>\\n\\t\\t\\t\\t            <a-button type=\\\"primary\\\" @click=\\\"tableRef.refresh(true)\\\">\\n\\t\\t\\t\\t                <template #icon><SearchOutlined /></template>\\n\\t\\t\\t\\t                查询\\n\\t\\t\\t\\t            </a-button>\\n\\t\\t\\t\\t            <a-button @click=\\\"reset\\\">\\n\\t\\t\\t\\t                <template #icon><redo-outlined /></template>\\n\\t\\t\\t\\t                 重置\\n\\t\\t\\t\\t            </a-button>\\n                        </a-space>\\n                    </a-form-item>\\n                </a-col>\\n            </a-row>\\n\\t\\t</a-form>\\n\\t\\t<s-table\\n\\t\\t\\tref=\\\"tableRef\\\"\\n\\t\\t\\t:columns=\\\"columns\\\"\\n\\t\\t\\t:data=\\\"loadData\\\"\\n\\t\\t\\t:alert=\\\"options.alert.show\\\"\\n\\t\\t\\tbordered\\n\\t\\t\\t:row-key=\\\"(record) => record.id\\\"\\n\\t\\t\\t:tool-config=\\\"toolConfig\\\"\\n\\t\\t\\t:row-selection=\\\"options.rowSelection\\\"\\n\\t\\t\\t:scroll=\\\"{ x: \'max-content\' }\\\"\\n\\t\\t>\\n\\t\\t\\t<template #operator class=\\\"table-operator\\\">\\n\\t\\t\\t\\t<a-space>\\n\\t\\t\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"formRef.onOpen()\\\" v-if=\\\"hasPerm(\'ewmProjectAdd\')\\\">\\n\\t\\t\\t\\t\\t\\t<template #icon><plus-outlined /></template>\\n\\t\\t\\t\\t\\t\\t新增\\n\\t\\t\\t\\t\\t</a-button>\\n\\t\\t\\t\\t\\t<a-button @click=\\\"importModelRef.onOpen()\\\" v-if=\\\"hasPerm(\'ewmProjectImport\')\\\">\\n                        <template #icon><import-outlined /></template>\\n                        <span>导入</span>\\n                    </a-button>\\n                    <a-button @click=\\\"exportData\\\" v-if=\\\"hasPerm(\'ewmProjectExport\')\\\">\\n                        <template #icon><export-outlined /></template>\\n                        <span>导出</span>\\n                    </a-button>\\n\\t\\t\\t\\t\\t<xn-batch-button\\n\\t\\t\\t\\t\\t\\tv-if=\\\"hasPerm(\'ewmProjectBatchDelete\')\\\"\\n\\t\\t\\t\\t\\t\\tbuttonName=\\\"批量删除\\\"\\n\\t\\t\\t\\t\\t\\ticon=\\\"DeleteOutlined\\\"\\n\\t\\t\\t\\t\\t\\tbuttonDanger\\n\\t\\t\\t\\t\\t\\t:selectedRowKeys=\\\"selectedRowKeys\\\"\\n\\t\\t\\t\\t\\t\\t@batchCallBack=\\\"deleteBatchEwmProject\\\"\\n\\t\\t\\t\\t\\t/>\\n\\t\\t\\t\\t</a-space>\\n\\t\\t\\t</template>\\n\\t\\t\\t<template #bodyCell=\\\"{ column, record }\\\">\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'orgId\'\\\">\\n\\t\\t\\t\\t\\t{{ $TOOL.dictTypeData(\'ORG_CATEGORY\', record.orgId) }}\\n\\t\\t\\t\\t</template>\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'peojectStatus\'\\\">\\n\\t\\t\\t\\t\\t{{ $TOOL.dictTypeData(\'PEOJECT_STATUS\', record.peojectStatus) }}\\n\\t\\t\\t\\t</template>\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'action\'\\\">\\n\\t\\t\\t\\t\\t<a-space>\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"formRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'ewmProjectEdit\')\\\">编辑</a>\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'ewmProjectEdit\', \'ewmProjectDelete\'], \'and\')\\\" />\\n\\t\\t\\t\\t\\t\\t<a-popconfirm title=\\\"确定要删除吗？\\\" @confirm=\\\"deleteEwmProject(record)\\\">\\n\\t\\t\\t\\t\\t\\t\\t<a-button type=\\\"link\\\" danger size=\\\"small\\\" v-if=\\\"hasPerm(\'ewmProjectDelete\')\\\">删除</a-button>\\n\\t\\t\\t\\t\\t\\t</a-popconfirm>\\n\\t\\t\\t\\t\\t</a-space>\\n\\t\\t\\t\\t</template>\\n\\t\\t\\t</template>\\n\\t\\t</s-table>\\n\\t</a-card>\\n\\t<ImportModel ref=\\\"importModelRef\\\" />\\n\\t<Form ref=\\\"formRef\\\" @successful=\\\"tableRef.refresh()\\\" />\\n</template>\\n\\n<script setup name=\\\"project\\\">\\n\\timport tool from \'@/utils/tool\'\\n\\timport { cloneDeep } from \'lodash-es\'\\n\\timport Form from \'./form.vue\'\\n\\timport ImportModel from \'./importModel.vue\'\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\n\\timport ewmProjectApi from \'@/api/ewm/ewmProjectApi\'\\n\\tconst searchFormState = ref({})\\n\\tconst searchFormRef = ref()\\n\\tconst tableRef = ref()\\n\\tconst importModelRef = ref()\\n\\tconst formRef = ref()\\n\\tconst toolConfig = { refresh: true, height: true, columnSetting: true, striped: false }\\n\\tconst columns = [\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目名称\',\\n\\t\\t\\tdataIndex: \'projectName\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目负责人\',\\n\\t\\t\\tdataIndex: \'projectLeader\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'机构id\',\\n\\t\\t\\tdataIndex: \'orgId\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目状态，WAIT-待开始,LOADING-进行中,OPERATION-运维中,STOP-项目结束\',\\n\\t\\t\\tdataIndex: \'peojectStatus\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目类别，integration-系统集成，develop-开发，safe-安全\',\\n\\t\\t\\tdataIndex: \'projectType\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目金额\',\\n\\t\\t\\tdataIndex: \'projectMoney\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目开始日期\',\\n\\t\\t\\tdataIndex: \'projectStartTime\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'项目结束日期\',\\n\\t\\t\\tdataIndex: \'projectEndTime\'\\n\\t\\t},\\n\\t]\\n\\t// 操作栏通过权限判断是否显示\\n\\tif (hasPerm([\'ewmProjectEdit\', \'ewmProjectDelete\'])) {\\n\\t\\tcolumns.push({\\n\\t\\t\\ttitle: \'操作\',\\n\\t\\t\\tdataIndex: \'action\',\\n\\t\\t\\talign: \'center\',\\n\\t\\t\\tfixed: \'right\'\\n\\t\\t})\\n\\t}\\n\\tconst selectedRowKeys = ref([])\\n\\t// 列表选择配置\\n\\tconst options = {\\n\\t\\talert: {\\n\\t\\t\\tshow: true,\\n\\t\\t\\tclear: () => {\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\n\\t\\t\\t}\\n\\t\\t},\\n\\t\\trowSelection: {\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\n\\t\\t\\t}\\n\\t\\t}\\n\\t}\\n\\tconst loadData = (parameter) => {\\n\\t\\tconst searchFormParam = cloneDeep(searchFormState.value)\\n\\t\\treturn ewmProjectApi.ewmProjectPage(Object.assign(parameter, searchFormParam)).then((data) => {\\n\\t\\t\\treturn data\\n\\t\\t})\\n\\t}\\n\\t// 重置\\n\\tconst reset = () => {\\n\\t\\tsearchFormRef.value.resetFields()\\n\\t\\ttableRef.value.refresh(true)\\n\\t}\\n\\t// 删除\\n\\tconst deleteEwmProject = (record) => {\\n\\t\\tlet params = [\\n\\t\\t\\t{\\n\\t\\t\\t\\tid: record.id\\n\\t\\t\\t}\\n\\t\\t]\\n\\t\\tewmProjectApi.ewmProjectDelete(params).then(() => {\\n\\t\\t\\ttableRef.value.refresh(true)\\n\\t\\t})\\n\\t}\\n\\t// 导出\\n    const exportData = () => {\\n        if (selectedRowKeys.value.length > 0) {\\n            const params = selectedRowKeys.value.map((m) => {\\n                return {\\n                    id: m\\n                }\\n            })\\n            ewmProjectApi.ewmProjectExport(params).then((res) => {\\n                downloadUtil.resultDownload(res)\\n            })\\n        } else {\\n            ewmProjectApi.ewmProjectExport([]).then((res) => {\\n                downloadUtil.resultDownload(res)\\n            })\\n        }\\n    }\\n\\t// 批量删除\\n\\tconst deleteBatchEwmProject = (params) => {\\n\\t\\tewmProjectApi.ewmProjectDelete(params).then(() => {\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\n\\t\\t})\\n\\t}\\n</script>\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\ewm\\\\project\\\\importModel.vue\",\"codeFileContent\":\"<template>\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\n\\t\\t</span>\\n\\t\\t<a-divider dashed />\\n\\t\\t<div>\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\n\\t\\t\\t\\t\\t</p>\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-text\\\">单击或拖动文件到此区域进行上传</p>\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-hint\\\">仅支持xls、xlsx格式文件</p>\\n\\t\\t\\t\\t</a-upload-dragger>\\n\\t\\t\\t</a-spin>\\n\\t\\t</div>\\n\\t\\t<a-alert v-if=\\\"impAlertStatus\\\" type=\\\"info\\\" :show-icon=\\\"false\\\" banner closable @close=\\\"onImpClose\\\" class=\\\"mt-3\\\">\\n\\t\\t\\t<template #description>\\n\\t\\t\\t\\t<p>导入总数：{{ impResultData.totalCount }} 条</p>\\n\\t\\t\\t\\t<p>导入成功：{{ impResultData.successCount }} 条</p>\\n\\t\\t\\t\\t<div v-if=\\\"impResultData.errorCount > 0\\\">\\n\\t\\t\\t\\t\\t<p><span class=\\\"xn-color-red\\\">失败条数：</span>{{ impResultData.errorCount }} 条</p>\\n\\t\\t\\t\\t\\t<a-table :dataSource=\\\"impResultErrorDataSource\\\" :columns=\\\"impErrorColumns\\\" size=\\\"small\\\" />\\n\\t\\t\\t\\t</div>\\n\\t\\t\\t</template>\\n\\t\\t</a-alert>\\n\\t</xn-form-container>\\n</template>\\n\\n<script setup name=\\\"ewmProjectImportModel\\\">\\n\\timport { message } from \'ant-design-vue\'\\n\\timport ewmProjectApi from \'@/api/ewm/ewmProjectApi\'\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\n\\n\\tconst impUploadLoading = ref(false)\\n\\tconst impAlertStatus = ref(false)\\n\\tconst impResultData = ref({})\\n\\tconst impResultErrorDataSource = ref([])\\n\\tconst impAccept = [\\n\\t\\t{\\n\\t\\t\\textension: \'.xls\',\\n\\t\\t\\tmimeType: \'application/vnd.ms-excel\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\textension: \'.xlsx\',\\n\\t\\t\\tmimeType: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\'\\n\\t\\t}\\n\\t]\\n\\t// 指定能选择的文件类型\\n\\tconst uploadAccept = String(\\n\\t\\timpAccept.map((item) => {\\n\\t\\t\\treturn item.mimeType\\n\\t\\t})\\n\\t)\\n\\t// 导入\\n\\tconst customRequestLocal = (data) => {\\n\\t\\timpUploadLoading.value = true\\n\\t\\tconst fileData = new FormData()\\n\\t\\t// 校验上传文件扩展名和文件类型是否为.xls、.xlsx\\n\\t\\tconst extension = \'.\'.concat(data.file.name.split(\'.\').slice(-1).toString().toLowerCase())\\n\\t\\tconst mimeType = data.file.type\\n\\t\\t// 提取允许的扩展名\\n\\t\\tconst extensionArr = impAccept.map((item) => item.extension)\\n\\t\\t// 提取允许的MIMEType\\n\\t\\tconst mimeTypeArr = impAccept.map((item) => item.mimeType)\\n\\t\\tif (!extensionArr.includes(extension) || !mimeTypeArr.includes(mimeType)) {\\n\\t\\t\\tmessage.warning(\'上传文件类型仅支持xls、xlsx格式文件！\')\\n\\t\\t\\timpUploadLoading.value = false\\n\\t\\t\\treturn false\\n\\t\\t}\\n\\t\\tfileData.append(\'file\', data.file)\\n\\t\\treturn e