INSERT INTO `dev_log` VALUES ('2017169915437391874', 'OPERATE', '预览代码生成', 'SUCCESS', NULL, '127.0.0.1', '内网IP|内网IP', 'Chrome', 'Windows 10 or Windows Server 2016', 'vip.xiaonuo.gen.modular.basic.controller.GenBasicController', 'previewGen', '/gen/basic/previewGen', '/gen/basic/previewGen', '{\"genBasicIdParam\":\"{\\\"id\\\":\\\"2017169497625993218\\\"}\"}', '{\"code\":200,\"msg\":\"操作成功\",\"data\":{\"genBasicCodeSqlResultList\":[{\"codeFileName\":\"Mysql.sql\",\"codeFileWithPathName\":\"sql\\\\Mysql.sql\",\"codeFileContent\":\"/*\\n Source Server Type: MySQL\\n Date:  2026/01/30 17:35\\n*/\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146177\', \'0\', \'文件管理表管理\', \'sysfiles\', \'j9PUwzaEZ1\', \'MENU\', \'1548901111999773976\', \'MENU\', \'/filemanger/sysfiles\', \'filemanger/sysfiles/index\', NULL, NULL, NULL, NULL, NULL, 99, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146178\', \'2017169912820146177\', \'新增文件管理表\', NULL, \'sysFilesAdd\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146181\', \'2017169912820146177\', \'批量删除文件管理表\', NULL, \'sysFilesBatchDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146179\', \'2017169912820146177\', \'编辑文件管理表\', NULL, \'sysFilesEdit\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146180\', \'2017169912820146177\', \'删除文件管理表\', NULL, \'sysFilesDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146182\', \'2017169912820146177\', \'导入文件管理表\', NULL, \'sysFilesImport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2017169912820146183\', \'2017169912820146177\', \'导出文件管理表\', NULL, \'sysFilesExport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\n\"},{\"codeFileName\":\"Oracle.sql\",\"codeFileWithPathName\":\"sql\\\\Oracle.sql\",\"codeFileContent\":\"/*\\n Source Server Type: Oracle\\n Date:  2026/01/30 17:35\\n*/\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2017169912820146177\', \'0\', \'文件管理表管理\', \'sysfiles\', \'j9PUwzaEZ1\', \'MENU\', \'1548901111999773976\', \'MENU\', \'/filemanger/sysfiles\', \'filemanger/sysfiles/index\', NULL, NULL, NULL, NULL, NULL, \'99\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2017169912820146178\', \'2017169912820146177\', \'新增文件管理表\', NULL, \'sysFilesAdd\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'1\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2017169912820146181\', \'2017169912820146177\', \'批量删除文件管理表\', NULL, \'sysFilesBatchDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'2\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2017169912820146179\', \'2017169912820146177\', \'编辑文件管理表\', NULL, \'sysFilesEdit\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'3\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2017169912820146180\', \'2017169912820146177\', \'删除文件管理表\', NULL, \'sysFilesDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'4\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALU