NULL, NULL, \'4\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2020769047582396422\', \'2020769047582396417\', \'导入网络安全的客户端\', NULL, \'ewmProjectSafeImport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'5\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2020769047582396423\', \'2020769047582396417\', \'导出网络安全的客户端\', NULL, \'ewmProjectSafeExport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'6\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\n\\n\"}],\"genBasicCodeFrontendResultList\":[{\"codeFileName\":\"ewmProjectSafeApi.js\",\"codeFileWithPathName\":\"api\\\\biz\\\\ewmProjectSafeApi.js\",\"codeFileContent\":\"import { baseRequest } from \'@/utils/request\'\\n\\nconst request = (url, ...arg) => baseRequest(`/biz/projectsafe/` + url, ...arg)\\n\\n/**\\n * 网络安全的客户端Api接口管理器\\n *\\n * @author Richai\\n * @date  2026/02/09 15:57\\n **/\\nexport default {\\n\\t// 获取网络安全的客户端分页\\n\\tewmProjectSafePage(data) {\\n\\t\\treturn request(\'page\', data, \'get\')\\n\\t},\\n\\t// 提交网络安全的客户端表单 edit为true时为编辑，默认为新增\\n\\tewmProjectSafeSubmitForm(data, edit = false) {\\n\\t\\treturn request(edit ? \'edit\' : \'add\', data)\\n\\t},\\n\\t// 删除网络安全的客户端\\n\\tewmProjectSafeDelete(data) {\\n\\t\\treturn request(\'delete\', data)\\n\\t},\\n\\t// 获取网络安全的客户端详情\\n\\tewmProjectSafeDetail(data) {\\n\\t\\treturn request(\'detail\', data, \'get\')\\n\\t},\\n\\t// 下载网络安全的客户端导入模板\\n    ewmProjectSafeDownloadTemplate(data) {\\n        return request(\'downloadImportTemplate\', data, \'get\', {\\n            responseType: \'blob\'\\n        })\\n    },\\n    // 导入网络安全的客户端\\n    ewmProjectSafeImport(data) {\\n        return request(\'importData\', data)\\n    },\\n    // 导出网络安全的客户端\\n    ewmProjectSafeExport(data) {\\n        return request(\'exportData\', data, \'post\', {\\n            responseType: \'blob\'\\n        })\\n    }\\n}\\n\"},{\"codeFileName\":\"form.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\projectsafe\\\\form.vue\",\"codeFileContent\":\"<template>\\n\\t<xn-form-container\\n\\t\\t:title=\\\"formData.id ? \'编辑网络安全的客户端\' : \'增加网络安全的客户端\'\\\"\\n\\t\\t:width=\\\"700\\\"\\n\\t\\tv-model:open=\\\"open\\\"\\n\\t\\t:destroy-on-close=\\\"true\\\"\\n\\t\\t@close=\\\"onClose\\\"\\n\\t>\\n\\t\\t<a-form ref=\\\"formRef\\\" :model=\\\"formData\\\" :rules=\\\"formRules\\\" layout=\\\"vertical\\\">\\n\\t\\t\\t<a-row :gutter=\\\"16\\\">\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"所属项目：\\\" name=\\\"projectId\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectId\\\" placeholder=\\\"请输入所属项目\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"秘钥：\\\" name=\\\"safeSecret\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeSecret\\\" placeholder=\\\"请输入秘钥\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"名称：\\\" name=\\\"safeName\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeName\\\" placeholder=\\\"请输入名称\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"机器码：\\\" name=\\\"safeCode\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeCode\\\" placeholder=\\\"请输入机器码\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"操作系统：\\\" name=\\\"safeOs\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeOs\\\" placeholder=\\\"请输入操作系统\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"IP地址：\\\" name=\\\"safeIp\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeIp\\\" placeholder=\\\"请输入IP地址\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"状态，ON-在线，OFF离线：\\\" name=\\\"safeStatus\\\">\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeStatus\\\" placeholder=\\\"请输入状态，ON-在线，OFF离线\\\" allow-clear />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"授权开始时间：\\\" name=\\\"safeStartTime\\\">\\n\\t\\t\\t\\t\\t\\t<a-date-picker v-model:value=\\\"formData.safeStartTime\\\" value-format=\\\"YYYY-MM-DD HH:mm:ss\\\" show-time placeholder=\\\"请选择授权开始时间\\\" style=\\\"width: 100%\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"授权结束时间：\\\" name=\\\"safeEndTime\\\">\\n\\t\\t\\t\\t\\t\\t<a-date-picker v-model:value=\\\"formData.safeEndTime\\\" value-format=\\\"YYYY-MM-DD HH:mm:ss\\\" show-time placeholder=\\\"请选择授权结束时间\\\" style=\\\"width: 100%\\\" />\\n\\t\\t\\t\\t\\t</a-form-item>\\n\\t\\t\\t\\t</a-col>\\n\\t\\t\\t</a-row>\\n\\t\\t</a-form>\\n\\t\\t<template #footer>\\n\\t\\t\\t<a-button style=\\\"margin-right: 8px\\\" @click=\\\"onClose\\\">关闭</a-button>\\n\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"onSubmit\\\" :loading=\\\"submitLoading\\\">保存</a-button>\\n\\t\\t</template>\\n\\t</xn-form-container>\\n</template>\\n\\n<script setup name=\\\"ewmProjectSafeForm\\\">\\n\\timport { cloneDeep } from \'lodash-es\'\\n\\timport { required } from \'@/utils/formRules\'\\n\\timport ewmProjectSafeApi from \'@/api/biz/ewmProjectSafeApi\'\\n\\t// 抽屉状态\\n\\tconst open = ref(false)\\n\\tconst emit = defineEmits({ successful: null })\\n\\tconst formRef = ref()\\n\\t// 表单数据\\n\\tconst formData = ref({})\\n\\tconst submitLoading = ref(false)\\n\\n\\t// 打开抽屉\\n\\tconst onOpen = (record) => {\\n\\t\\topen.value = true\\n\\t\\tif (record) {\\n\\t\\t\\tlet recordData = cloneDeep(record)\\n\\t\\t\\tformData.value = Object.assign({}, recordData)\\n\\t\\t}\\n\\t}\\n\\t// 关闭抽屉\\n\\tconst onClose = () => {\\n\\t\\tformRef.value.resetFields()\\n\\t\\tformData.value = {}\\n\\t\\topen.value = false\\n\\t}\\n\\t// 默认要校验的\\n\\tconst formRules = {\\n\\t}\\n\\t// 验证并提交数据\\n\\tconst onSubmit = () => {\\n\\t\\tformRef.value\\n\\t\\t\\t.validate()\\n\\t\\t\\t.then(() => {\\n\\t\\t\\t\\tsubmitLoading.value = true\\n\\t\\t\\t\\tconst formDataParam = cloneDeep(formData.value)\\n\\t\\t\\t\\tewmProjectSafeApi\\n\\t\\t\\t\\t\\t.ewmProjectSafeSubmitForm(formDataParam, formDataParam.id)\\n\\t\\t\\t\\t\\t.then(() => {\\n\\t\\t\\t\\t\\t\\tonClose()\\n\\t\\t\\t\\t\\t\\temit(\'successful\')\\n\\t\\t\\t\\t\\t})\\n\\t\\t\\t\\t\\t.finally(() => {\\n\\t\\t\\t\\t\\t\\tsubmitLoading.value = false\\n\\t\\t\\t\\t\\t})\\n\\t\\t\\t})\\n\\t\\t\\t.catch(() => {})\\n\\t}\\n\\t// 抛出函数\\n\\tdefineExpose({\\n\\t\\tonOpen\\n\\t})\\n</script>\\n\"},{\"codeFileName\":\"index.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\projectsafe\\\\index.vue\",\"codeFileContent\":\"<template>\\n\\t<a-card :bordered=\\\"false\\\" style=\\\"width: 100%\\\">\\n\\t\\t<s-table\\n\\t\\t\\tref=\\\"tableRef\\\"\\n\\t\\t\\t:columns=\\\"columns\\\"\\n\\t\\t\\t:data=\\\"loadData\\\"\\n\\t\\t\\t:alert=\\\"options.alert.show\\\"\\n\\t\\t\\tbordered\\n\\t\\t\\t:row-key=\\\"(record) => record.id\\\"\\n\\t\\t\\t:tool-config=\\\"toolConfig\\\"\\n\\t\\t\\t:row-selection=\\\"options.rowSelection\\\"\\n\\t\\t\\t:scroll=\\\"{ x: \'max-content\' }\\\"\\n\\t\\t>\\n\\t\\t\\t<template #operator class=\\\"table-operator\\\">\\n\\t\\t\\t\\t<a-space>\\n\\t\\t\\t\\t\\t<a-button type=\\\"primary\\\" @click=\\\"formRef.onOpen()\\\" v-if=\\\"hasPerm(\'ewmProjectSafeAdd\')\\\">\\n\\t\\t\\t\\t\\t\\t<template #icon><plus-outlined /></template>\\n\\t\\t\\t\\t\\t\\t新增\\n\\t\\t\\t\\t\\t</a-button>\\n\\t\\t\\t\\t\\t<a-button @click=\\\"importModelRef.onOpen()\\\" v-if=\\\"hasPerm(\'ewmProjectSafeImport\')\\\">\\n                        <template #icon><import-outlined /></template>\\n                        <span>导入</span>\\n                    </a-button>\\n                    <a-button @click=\\\"exportData\\\" v-if=\\\"hasPerm(\'ewmProjectSafeExport\')\\\">\\n                        <template #icon><export-outlined /></template>\\n                        <span>导出</span>\\n                    </a-button>\\n\\t\\t\\t\\t\\t<xn-batch-button\\n\\t\\t\\t\\t\\t\\tv-if=\\\"hasPerm(\'ewmProjectSafeBatchDelete\')\\\"\\n\\t\\t\\t\\t\\t\\tbuttonName=\\\"批量删除\\\"\\n\\t\\t\\t\\t\\t\\ticon=\\\"DeleteOutlined\\\"\\n\\t\\t\\t\\t\\t\\tbuttonDanger\\n\\t\\t\\t\\t\\t\\t:selectedRowKeys=\\\"selectedRowKeys\\\"\\n\\t\\t\\t\\t\\t\\t@batchCallBack=\\\"deleteBatchEwmProjectSafe\\\"\\n\\t\\t\\t\\t\\t/>\\n\\t\\t\\t\\t</a-space>\\n\\t\\t\\t</template>\\n\\t\\t\\t<template #bodyCell=\\\"{ column, record }\\\">\\n\\t\\t\\t\\t<template v-if=\\\"column.dataIndex === \'action\'\\\">\\n\\t\\t\\t\\t\\t<a-space>\\n\\t\\t\\t\\t\\t\\t<a @click=\\\"formRef.onOpen(record)\\\" v-if=\\\"hasPerm(\'ewmProjectSafeEdit\')\\\">编辑</a>\\n\\t\\t\\t\\t\\t\\t<a-divider type=\\\"vertical\\\" v-if=\\\"hasPerm([\'ewmProjectSafeEdit\', \'ewmProjectSafeDelete\'], \'and\')\\\" />\\n\\t\\t\\t\\t\\t\\t<a-popconfirm title=\\\"确定要删除吗？\\\" @confirm=\\\"deleteEwmProjectSafe(record)\\\">\\n\\t\\t\\t\\t\\t\\t\\t<a-button type=\\\"link\\\" danger size=\\\"small\\\" v-if=\\\"hasPerm(\'ewmProjectSafeDelete\')\\\">删除</a-button>\\n\\t\\t\\t\\t\\t\\t</a-popconfirm>\\n\\t\\t\\t\\t\\t</a-space>\\n\\t\\t\\t\\t</template>\\n\\t\\t\\t</template>\\n\\t\\t</s-table>\\n\\t</a-card>\\n\\t<ImportModel ref=\\\"importModelRef\\\" />\\n\\t<Form ref=\\\"formRef\\\" @successful=\\\"tableRef.refresh()\\\" />\\n</template>\\n\\n<script setup name=\\\"projectsafe\\\">\\n\\timport { cloneDeep } from \'lodash-es\'\\n\\timport Form from \'./form.vue\'\\n\\timport ImportModel from \'./importModel.vue\'\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\n\\timport ewmProjectSafeApi from \'@/api/biz/ewmProjectSafeApi\'\\n\\tconst tableRef = ref()\\n\\tconst importModelRef = ref()\\n\\tconst formRef = ref()\\n\\tconst toolConfig = { refresh: true, height: true, columnSetting: true, striped: false }\\n\\tconst columns = [\\n\\t\\t{\\n\\t\\t\\ttitle: \'所属项目\',\\n\\t\\t\\tdataIndex: \'projectId\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'秘钥\',\\n\\t\\t\\tdataIndex: \'safeSecret\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'名称\',\\n\\t\\t\\tdataIndex: \'safeName\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'机器码\',\\n\\t\\t\\tdataIndex: \'safeCode\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'操作系统\',\\n\\t\\t\\tdataIndex: \'safeOs\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'IP地址\',\\n\\t\\t\\tdataIndex: \'safeIp\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'状态，ON-在线，OFF离线\',\\n\\t\\t\\tdataIndex: \'safeStatus\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'授权开始时间\',\\n\\t\\t\\tdataIndex: \'safeStartTime\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'授权结束时间\',\\n\\t\\t\\tdataIndex: \'safeEndTime\'\\n\\t\\t},\\n\\t]\\n\\t// 操作栏通过权限判断是否显示\\n\\tif (hasPerm([\'ewmProjectSafeEdit\', \'ewmProjectSafeDelete\'])) {\\n\\t\\tcolumns.push({\\n\\t\\t\\ttitle: \'操作\',\\n\\t\\t\\tdataIndex: \'action\',\\n\\t\\t\\talign: \'center\',\\n\\t\\t\\tfixed: \'right\'\\n\\t\\t})\\n\\t}\\n\\tconst selectedRowKeys = ref([])\\n\\t// 列表选择配置\\n\\tconst options = {\\n\\t\\talert: {\\n\\t\\t\\tshow: true,\\n\\t\\t\\tclear: () => {\\n\\t\\t\\t\\tselectedRowKeys.value = ref([])\\n\\t\\t\\t}\\n\\t\\t},\\n\\t\\trowSelection: {\\n\\t\\t\\tonChange: (selectedRowKey, selectedRows) => {\\n\\t\\t\\t\\tselectedRowKeys.value = selectedRowKey\\n\\t\\t\\t}\\n\\t\\t}\\n\\t}\\n\\tconst loadData = (parameter) => {\\n\\t\\treturn ewmProjectSafeApi.ewmProjectSafePage(parameter).then((data) => {\\n\\t\\t\\treturn data\\n\\t\\t})\\n\\t}\\n\\t// 重置\\n\\tconst reset = () => {\\n\\t\\tsearchFormRef.value.resetFields()\\n\\t\\ttableRef.value.refresh(true)\\n\\t}\\n\\t// 删除\\n\\tconst deleteEwmProjectSafe = (record) => {\\n\\t\\tlet params = [\\n\\t\\t\\t{\\n\\t\\t\\t\\tid: record.id\\n\\t\\t\\t}\\n\\t\\t]\\n\\t\\tewmProjectSafeApi.ewmProjectSafeDelete(params).then(() => {\\n\\t\\t\\ttableRef.value.refresh(true)\\n\\t\\t})\\n\\t}\\n\\t// 导出\\n    const exportData = () => {\\n        if (selectedRowKeys.value.length > 0) {\\n            const params = selectedRowKeys.value.map((m) => {\\n                return {\\n                    id: m\\n                }\\n            })\\n            ewmProjectSafeApi.ewmProjectSafeExport(params).then((res) => {\\n                downloadUtil.resultDownload(res)\\n            })\\n        } else {\\n            ewmProjectSafeApi.ewmProjectSafeExport([]).then((res) => {\\n                downloadUtil.resultDownload(res)\\n            })\\n        }\\n    }\\n\\t// 批量删除\\n\\tconst deleteBatchEwmProjectSafe = (params) => {\\n\\t\\tewmProjectSafeApi.ewmProjectSafeDelete(params).then(() => {\\n\\t\\t\\ttableRef.value.clearRefreshSelected()\\n\\t\\t})\\n\\t}\\n</script>\\n\"},{\"codeFileName\":\"importModel.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\projectsafe\\\\importModel.vue\",\"codeFileContent\":\"<template>\\n\\t<xn-form-container title=\\\"导入导出\\\" :width=\\\"700\\\" :visible=\\\"visible\\\" :destroy-on-close=\\\"true\\\" @close=\\\"onClose\\\">\\n\\t\\t<span>导入数据格式严格按照系统模板进行数据录入，请点击&nbsp;<a-button type=\\\"primary\\\" size=\\\"small\\\" @click=\\\"downloadImportTemplate\\\">下载模板</a-button>\\n\\t\\t</span>\\n\\t\\t<a-divider dashed />\\n\\t\\t<div>\\n\\t\\t\\t<a-spin :spinning=\\\"impUploadLoading\\\">\\n\\t\\t\\t\\t<a-upload-dragger :show-upload-list=\\\"false\\\" :custom-request=\\\"customRequestLocal\\\" :accept=\\\"uploadAccept\\\">\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-drag-icon\\\">\\n\\t\\t\\t\\t\\t\\t<inbox-outlined></inbox-outlined>\\n\\t\\t\\t\\t\\t</p>\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-text\\\">单击或拖动文件到此区域进行上传</p>\\n\\t\\t\\t\\t\\t<p class=\\\"ant-upload-hint\\\">仅支持xls、xlsx格式文件</p>\\n\\t\\t\\t\\t</a-upload-dragger>\\n\\t\\t\\t</a-spin>\\n\\t\\t</div>\\n\\t\\t<a-alert v-if=\\\"impAlertStatus\\\" type=\\\"info\\\" :show-icon=\\\"false\\\" banner closable @close=\\\"onImpClose\\\" class=\\\"mt-3\\\">\\n\\t\\t\\t<template #description>\\n\\t\\t\\t\\t<p>导入总数：{{ impResultData.totalCount }} 条</p>\\n\\t\\t\\t\\t<p>导入成功：{{ impResultData.successCount }} 条</p>\\n\\t\\t\\t\\t<div v-if=\\\"impResultData.errorCount > 0\\\">\\n\\t\\t\\t\\t\\t<p><span class=\\\"xn-color-red\\\">失败条数：</span>{{ impResultData.errorCount }} 条</p>\\n\\t\\t\\t\\t\\t<a-table :dataSource=\\\"impResultErrorDataSource\\\" :columns=\\\"impErrorColumns\\\" size=\\\"small\\\" />\\n\\t\\t\\t\\t</div>\\n\\t\\t\\t</template>\\n\\t\\t</a-alert>\\n\\t</xn-form-container>\\n</template>\\n\\n<script setup name=\\\"ewmProjectSafeImportModel\\\">\\n\\timport { message } from \'ant-design-vue\'\\n\\timport ewmProjectSafeApi from \'@/api/biz/ewmProjectSafeApi\'\\n\\timport downloadUtil from \'@/utils/downloadUtil\'\\n\\n\\tconst impUploadLoading = ref(false)\\n\\tconst impAlertStatus = ref(false)\\n\\tconst impResultData = ref({})\\n\\tconst impResultErrorDataSource = ref([])\\n\\tconst impAccept = [\\n\\t\\t{\\n\\t\\t\\textension: \'.xls\',\\n\\t\\t\\tmimeType: \'application/vnd.ms-excel\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\textension: \'.xlsx\',\\n\\t\\t\\tmimeType: \'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\'\\n\\t\\t}\\n\\t]\\n\\t// 指定能选择的文件类型\\n\\tconst uploadAccept = String(\\n\\t\\timpAccept.map((item) => {\\n\\t\\t\\treturn item.mimeType\\n\\t\\t})\\n\\t)\\n\\t// 导入\\n\\tconst customRequestLocal = (data) => {\\n\\t\\timpUploadLoading.value = true\\n\\t\\tconst fileData = new FormData()\\n\\t\\t// 校验上传文件扩展名和文件类型是否为.xls、.xlsx\\n\\t\\tconst extension = \'.\'.concat(data.file.name.split(\'.\').slice(-1).toString().toLowerCase())\\n\\t\\tconst mimeType = data.file.type\\n\\t\\t// 提取允许的扩展名\\n\\t\\tconst extensionArr = impAccept.map((item) => item.extension)\\n\\t\\t// 提取允许的MIMEType\\n\\t\\tconst mimeTypeArr = impAccept.map((item) => item.mimeType)\\n\\t\\tif (!extensionArr.includes(extension) || !mimeTypeArr.includes(mimeType)) {\\n\\t\\t\\tmessage.warning(\'上传文件类型仅支持xls、xlsx格式文件！\')\\n\\t\\t\\timpUploadLoading.value = false\\n\\t\\t\\treturn false\\n\\t\\t}\\n\\t\\tfileData.append(\'file\', data.file)\\n\\t\\treturn ewmProjectSafeApi\\n\\t\\t\\t.ewmProjectSafeImport(fileData)\\n\\t\\t\\t.then((res) => {\\n\\t\\t\\t\\timpAlertStatus.value = true\\n\\t\\t\\t\\timpResultData.value = res\\n\\t\\t\\t\\timpResultErrorDataSource.value = res.errorDetail\\n\\t\\t\\t})\\n\\t\\t\\t.finally(() => {\\n\\t\\t\\t\\timpUploadLoading.value = false\\n\\t\\t\\t})\\n\\t}\\n\\t// 关闭导入提示\\n\\tconst onImpClose = () => {\\n\\t\\timpAlertStatus.value = false\\n\\t}\\n\\tconst impErrorColumns = [\\n\\t\\t{\\n\\t\\t\\ttitle: \'索引\',\\n\\t\\t\\tdataIndex: \'index\',\\n\\t\\t\\twidth: \'80px\'\\n\\t\\t},\\n\\t\\t{\\n\\t\\t\\ttitle: \'原因\',\\n\\t\\t\\tdataIndex: \'msg\'\\n\\t\\t}\\n\\t]\\n\\t// 定义emit事件\\n\\tconst emit = defineEmits({ successful: null })\\n\\t// 默认是关闭状态\\n\\tconst visible = ref(false)\\n\\tconst submitLoading = ref(false)\\n\\n\\t// 打开抽屉\\n\\tconst onOpen = () => {\\n\\t\\tvisible.value = true\\n\\t}\\n\\t// 关闭抽屉\\n\\tconst onClose = () => {\\n\\t\\tvisible.value = false\\n\\t\\t// 关闭导入的提示\\n\\t\\tonImpClose()\\n\\t}\\n\\t// 下载导入模板\\n\\tconst downloadImportTemplate = () => {\\n\\t\\