ringframework.web.multipart.MultipartFile;\\nimport vip.xiaonuo.common.enums.CommonSortOrderEnum;\\nimport vip.xiaonuo.common.exception.CommonException;\\nimport vip.xiaonuo.common.page.CommonPageRequest;\\nimport java.math.BigDecimal;\\nimport java.util.Date;\\nimport vip.xiaonuo.biz.modular.projectsafe.entity.EwmProjectSafe;\\nimport vip.xiaonuo.biz.modular.projectsafe.mapper.EwmProjectSafeMapper;\\nimport vip.xiaonuo.biz.modular.projectsafe.param.EwmProjectSafeAddParam;\\nimport vip.xiaonuo.biz.modular.projectsafe.param.EwmProjectSafeEditParam;\\nimport vip.xiaonuo.biz.modular.projectsafe.param.EwmProjectSafeIdParam;\\nimport vip.xiaonuo.biz.modular.projectsafe.param.EwmProjectSafePageParam;\\nimport vip.xiaonuo.biz.modular.projectsafe.service.EwmProjectSafeService;\\n\\nimport vip.xiaonuo.common.util.CommonDownloadUtil;\\nimport vip.xiaonuo.common.util.CommonResponseUtil;\\n\\nimport java.io.File;\\nimport java.io.IOException;\\nimport java.util.List;\\n\\n/**\\n * 网络安全的客户端Service接口实现类\\n *\\n * @author Richai\\n * @date  2026/02/09 15:57\\n **/\\n@Service\\npublic class EwmProjectSafeServiceImpl extends ServiceImpl<EwmProjectSafeMapper, EwmProjectSafe> implements EwmProjectSafeService {\\n\\n    @Override\\n    public Page<EwmProjectSafe> page(EwmProjectSafePageParam ewmProjectSafePageParam) {\\n        QueryWrapper<EwmProjectSafe> queryWrapper = new QueryWrapper<EwmProjectSafe>().checkSqlInjection();\\n        if(ObjectUtil.isAllNotEmpty(ewmProjectSafePageParam.getSortField(), ewmProjectSafePageParam.getSortOrder())) {\\n            CommonSortOrderEnum.validate(ewmProjectSafePageParam.getSortOrder());\\n            queryWrapper.orderBy(true, ewmProjectSafePageParam.getSortOrder().equals(CommonSortOrderEnum.ASC.getValue()),\\n                    StrUtil.toUnderlineCase(ewmProjectSafePageParam.getSortField()));\\n        } else {\\n            queryWrapper.lambda().orderByAsc(EwmProjectSafe::getId);\\n        }\\n        return this.page(CommonPageRequest.defaultPage(), queryWrapper);\\n    }\\n\\n    @Transactional(rollbackFor = Exception.class)\\n    @Override\\n    public void add(EwmProjectSafeAddParam ewmProjectSafeAddParam) {\\n        EwmProjectSafe ewmProjectSafe = BeanUtil.toBean(ewmProjectSafeAddParam, EwmProjectSafe.class);\\n        this.save(ewmProjectSafe);\\n    }\\n\\n    @Transactional(rollbackFor = Exception.class)\\n    @Override\\n    public void edit(EwmProjectSafeEditParam ewmProjectSafeEditParam) {\\n        EwmProjectSafe ewmProjectSafe = this.queryEntity(ewmProjectSafeEditParam.getId());\\n        BeanUtil.copyProperties(ewmProjectSafeEditParam, ewmProjectSafe);\\n        this.updateById(ewmProjectSafe);\\n    }\\n\\n    @Transactional(rollbackFor = Exception.class)\\n    @Override\\n    public void delete(List<EwmProjectSafeIdParam> ewmProjectSafeIdParamList) {\\n        // 执行删除\\n        this.removeByIds(CollStreamUtil.toList(ewmProjectSafeIdParamList, EwmProjectSafeIdParam::getId));\\n    }\\n\\n    @Override\\n    public EwmProjectSafe detail(EwmProjectSafeIdParam ewmProjectSafeIdParam) {\\n        return this.queryEntity(ewmProjectSafeIdParam.getId());\\n    }\\n\\n    @Override\\n    public EwmProjectSafe queryEntity(String id) {\\n        EwmProjectSafe ewmProjectSafe = this.getById(id);\\n        if(ObjectUtil.isEmpty(ewmProjectSafe)) {\\n            throw new CommonException(\\\"网络安全的客户端不存在，id值为：{}\\\", id);\\n        }\\n        return ewmProjectSafe;\\n    }\\n\\n    @Override\\n    public void downloadImportTemplate(HttpServletResponse response) throws IOException {\\n       File tempFile = null;\\n       try {\\n         List<EwmProjectSafeEditParam> dataList = CollectionUtil.newArrayList();\\n         String fileName = \\\"网络安全的客户端导入模板_\\\" + DateUtil.format(DateTime.now(), DatePattern.PURE_DATETIME_PATTERN) + \\\".xlsx\\\";\\n         tempFile = FileUtil.file(FileUtil.getTmpDir() + FileUtil.FILE_SEPARATOR + fileName);\\n         EasyExcel.write(tempFile.getPath(), EwmProjectSafeEditParam.class).sheet(\\\"网络安全的客户端\\\").doWrite(dataList);\\n         CommonDownloadUtil.download(tempFile, response);\\n       } catch (Exception e) {\\n         log.error(\\\">>> 网络安全的客户端导入模板下载失败：\\\", e);\\n         CommonResponseUtil.renderError(response, \\\"网络安全的客户端导入模板下载失败\\\");\\n       } finally {\\n         FileUtil.del(tempFile);\\n       }\\n    }\\n\\n    @Transactional(rollbackFor = Exception.class)\\n    @Override\\n    public JSONObject importData(MultipartFile file) {\\n        try {\\n            int successCount = 0;\\n            int errorCount = 0;\\n            JSONArray errorDetail = JSONUtil.createArray();\\n            // 创建临时文件\\n            File tempFile = FileUtil.writeBytes(file.getBytes(), FileUtil.file(FileUtil.getTmpDir() +\\n                    FileUtil.FILE_SEPARATOR + \\\"ewmProjectSafeImportTemplate.xlsx\\\"));\\n            // 读取excel\\n            List<EwmProjectSafeEditParam> ewmProjectSafeEditParamList =  EasyExcel.read(tempFile).head(EwmProjectSafeEditParam.class).sheet()\\n                    .headRowNumber(1).doReadSync();\\n            List<EwmProjectSafe> allDataList = this.list();\\n            for (int i = 0; i < ewmProjectSafeEditParamList.size(); i++) {\\n                JSONObject jsonObject = this.doImport(allDataList, ewmProjectSafeEditParamList.get(i), i);\\n                if(jsonObject.getBool(\\\"success\\\")) {\\n                    successCount += 1;\\n                } else {\\n                    errorCount += 1;\\n                    errorDetail.add(jsonObject);\\n                }\\n            }\\n            return JSONUtil.createObj()\\n                    .set(\\\"totalCount\\\", ewmProjectSafeEditParamList.size())\\n                    .set(\\\"successCount\\\", successCount)\\n                    .set(\\\"errorCount\\\", errorCount)\\n                    .set(\\\"errorDetail\\\", errorDetail);\\n        } catch (Exception e) {\\n            log.error(\\\">>> 网络安全的客户端导入失败：\\\", e);\\n            throw new CommonException(\\\"网络安全的客户端导入失败\\\");\\n        }\\n    }\\n\\n    public JSONObject doImport(List<EwmProjectSafe> allDataList, EwmProjectSafeEditParam ewmProjectSafeEditParam, int i) {\\n        String id = ewmProjectSafeEditParam.getId();\\n        if(ObjectUtil.hasEmpty(id)) {\\n            return JSONUtil.createObj().set(\\\"index\\\", i + 1).set(\\\"success\\\", false).set(\\\"msg\\\", \\\"必填字段存在空值\\\");\\n        } else {\\n            try {\\n                int index = CollStreamUtil.toList(allDataList, EwmProjectSafe::getId).indexOf(ewmProjectSafeEditParam.getId());\\n                EwmProjectSafe ewmProjectSafe;\\n                boolean isAdd = false;\\n                if(index == -1) {\\n                    isAdd = true;\\n                    ewmProjectSafe = new EwmProjectSafe();\\n                } else {\\n                    ewmProjectSafe = allDataList.get(index);\\n                }\\n                BeanUtil.copyProperties(ewmProjectSafeEditParam, ewmProjectSafe);\\n                if(isAdd) {\\n                    allDataList.add(ewmProjectSafe);\\n                } else {\\n                    allDataList.remove(index);\\n                    allDataList.add(index, ewmProjectSafe);\\n                }\\n                this.saveOrUpdate(ewmProjectSafe);\\n                return JSONUtil.createObj().set(\\\"success\\\", true);\\n            } catch (Exception e) {\\n              log.error(\\\">>> 数据导入异常：\\\", e);\\n              return JSONUtil.createObj().set(\\\"success\\\", false).set(\\\"index\\\", i + 1).set(\\\"msg\\\", \\\"数据导入异常\\\");\\n            }\\n        }\\n    }\\n\\n    @Override\\n    public void exportData(List<EwmProjectSafeIdParam> ewmProjectSafeIdParamList, HttpServletResponse response) throws IOException {\\n       File tempFile = null;\\n       try {\\n         List<EwmProjectSafeEditParam> dataList;\\n         if(ObjectUtil.isNotEmpty(ewmProjectSafeIdParamList)) {\\n            List<String> idList = CollStreamUtil.toList(ewmProjectSafeIdParamList, EwmProjectSafeIdParam::getId);\\n            dataList = BeanUtil.copyToList(this.listByIds(idList), EwmProjectSafeEditParam.class);\\n         } else {\\n            dataList = BeanUtil.copyToList(this.list(), EwmProjectSafeEditParam.class);\\n         }\\n         String fileName = \\\"网络安全的客户端_\\\" + DateUtil.format(DateTime.now(), DatePattern.PURE_DATETIME_PATTERN) + \\\".xlsx\\\";\\n         tempFile = FileUtil.file(FileUtil.getTmpDir() + FileUtil.FILE_SEPARATOR + fileName);\\n         EasyExcel.write(tempFile.getPath(), EwmProjectSafeEditParam.class).sheet(\\\"网络安全的客户端\\\").doWrite(dataList);\\n         CommonDownloadUtil.download(tempFile, response);\\n       } catch (Exception e) {\\n         log.error(\\\">>> 网络安全的客户端导出失败：\\\", e);\\n         CommonResponseUtil.renderError(response, \\\"网络安全的客户端导出失败\\\");\\n       } finally {\\n         FileUtil.del(tempFile);\\n       }\\n    }\\n}\\n\"}]},\"traceId\":\"ddfe625946ca435a94de4de25c47cd04\"}', '2026-02-09 15:57:40', '超管', 'dfbe5aa4b302b3d6fd93d0039766937220a9ab2c187e368c487b3ffaefdaf72ac56210b27c723350161068de44c018410087b5b612f8bf1f47d026f2500e8c13', '2026-02-09 15:57:40', '-1', NULL, NULL);
