INSERT INTO `dev_log` VALUES ('2023053549635186689', 'OPERATE', '预览代码生成', 'SUCCESS', NULL, '127.0.0.1', '内网IP|内网IP', 'Chrome', 'Windows 10 or Windows Server 2016', 'vip.xiaonuo.gen.modular.basic.controller.GenBasicController', 'previewGen', '/gen/basic/previewGen', '/gen/basic/previewGen', '{\"genBasicIdParam\":\"{\\\"id\\\":\\\"2020768894100230146\\\"}\"}', '{\"code\":200,\"msg\":\"操作成功\",\"data\":{\"genBasicCodeSqlResultList\":[{\"codeFileName\":\"Mysql.sql\",\"codeFileWithPathName\":\"sql\\\\Mysql.sql\",\"codeFileContent\":\"/*\\r\\n Source Server Type: MySQL\\r\\n Date:  2026/02/15 23:15\\r\\n*/\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493570\', \'2005897753527431170\', \'网络安全的客户端管理\', \'projectsafe\', \'loUOYjDoHI\', \'MENU\', \'1548901111999773976\', \'MENU\', \'/biz/projectsafe\', \'biz/projectsafe/index\', NULL, NULL, NULL, NULL, NULL, 99, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493571\', \'2023053547936493570\', \'新增网络安全的客户端\', NULL, \'ewmProjectSafeAdd\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493574\', \'2023053547936493570\', \'批量删除网络安全的客户端\', NULL, \'ewmProjectSafeBatchDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493572\', \'2023053547936493570\', \'编辑网络安全的客户端\', NULL, \'ewmProjectSafeEdit\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493573\', \'2023053547936493570\', \'删除网络安全的客户端\', NULL, \'ewmProjectSafeDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493575\', \'2023053547936493570\', \'导入网络安全的客户端\', NULL, \'ewmProjectSafeImport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO `SYS_RESOURCE` VALUES (\'2023053547936493576\', \'2023053547936493570\', \'导出网络安全的客户端\', NULL, \'ewmProjectSafeExport\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\n\"},{\"codeFileName\":\"Oracle.sql\",\"codeFileWithPathName\":\"sql\\\\Oracle.sql\",\"codeFileContent\":\"/*\\r\\n Source Server Type: Oracle\\r\\n Date:  2026/02/15 23:15\\r\\n*/\\r\\n\\r\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2023053547936493570\', \'2005897753527431170\', \'网络安全的客户端管理\', \'projectsafe\', \'loUOYjDoHI\', \'MENU\', \'1548901111999773976\', \'MENU\', \'/biz/projectsafe\', \'biz/projectsafe/index\', NULL, NULL, NULL, NULL, NULL, \'99\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2023053547936493571\', \'2023053547936493570\', \'新增网络安全的客户端\', NULL, \'ewmProjectSafeAdd\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'1\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2023053547936493574\', \'2023053547936493570\', \'批量删除网络安全的客户端\', NULL, \'ewmProjectSafeBatchDelete\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'2\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2023053547936493572\', \'2023053547936493570\', \'编辑网络安全的客户端\', NULL, \'ewmProjectSafeEdit\', \'BUTTON\', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, \'3\', NULL, \'NOT_DELETE\', NULL, NULL, NULL, NULL);\\r\\n\\r\\nINSERT INTO \\\"SNOWY\\\".\\\"SYS_RESOURCE\\\" VALUES (\'2023053547936493573\', \'2023053547936493570\', \'删除网络