   return request(\'importData\', data)\\r\\n    },\\r\\n    // 导出网络安全的客户端\\r\\n    ewmProjectSafeExport(data) {\\r\\n        return request(\'exportData\', data, \'post\', {\\r\\n            responseType: \'blob\'\\r\\n        })\\r\\n    }\\r\\n}\\r\\n\"},{\"codeFileName\":\"form.vue\",\"codeFileWithPathName\":\"views\\\\biz\\\\projectsafe\\\\form.vue\",\"codeFileContent\":\"<template>\\r\\n\\t<xn-form-container\\r\\n\\t\\t:title=\\\"formData.id ? \'编辑网络安全的客户端\' : \'增加网络安全的客户端\'\\\"\\r\\n\\t\\t:width=\\\"700\\\"\\r\\n\\t\\tv-model:open=\\\"open\\\"\\r\\n\\t\\t:destroy-on-close=\\\"true\\\"\\r\\n\\t\\t@close=\\\"onClose\\\"\\r\\n\\t>\\r\\n\\t\\t<a-form ref=\\\"formRef\\\" :model=\\\"formData\\\" :rules=\\\"formRules\\\" layout=\\\"vertical\\\">\\r\\n\\t\\t\\t<a-row :gutter=\\\"16\\\">\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"所属项目：\\\" name=\\\"projectId\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.projectId\\\" placeholder=\\\"请输入所属项目\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"秘钥：\\\" name=\\\"safeSecret\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeSecret\\\" placeholder=\\\"请输入秘钥\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"名称：\\\" name=\\\"safeName\\\">\\r\\n\\t\\t\\t\\t\\t\\t<a-input v-model:value=\\\"formData.safeName\\\" placeholder=\\\"请输入名称\\\" allow-clear />\\r\\n\\t\\t\\t\\t\\t</a-form-item>\\r\\n\\t\\t\\t\\t</a-col>\\r\\n\\t\\t\\t\\t<a-col :xs=\\\"24\\\" :sm=\\\"24\\\" :md=\\\"12\\\" :lg=\\\"12\\\" :xl=\\\"12\\\">\\r\\n\\t\\t\\t\\t\\t<a-form-item label=\\\"机器码：\\